import{f as i,D as r,o as s,c as d,k as n,a as t,G as h,ar as l}from"./chunks/framework.W_ryyXug.js";const p=JSON.parse('{"title":"Health-Checks ohne DB- und LDAP-Verbindung","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-health-checks-ohne-db-ldap.md","filePath":"technik/adr/adr-health-checks-ohne-db-ldap.md"}'),o={name:"technik/adr/adr-health-checks-ohne-db-ldap.md"};function u(c,e,b,k,g,f){const a=r("adr-status");return s(),d("div",null,[e[0]||(e[0]=n("h1",{id:"health-checks-ohne-db-und-ldap-verbindung",tabindex:"-1"},[t("Health-Checks ohne DB- und LDAP-Verbindung "),n("a",{class:"header-anchor",href:"#health-checks-ohne-db-und-ldap-verbindung","aria-label":'Permalink to "Health-Checks ohne DB- und LDAP-Verbindung"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[t("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),h(a,{status:"accepted"}),e[2]||(e[2]=l('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Unsere Services werden über Health-Checks überwacht. Bisher flossen dabei auch die Verfügbarkeit der Datenbank und des LDAP in den allgemeinen Health-Status ein. Das führte in der Praxis zu folgenden Problemen:</p><ul><li>Ist die Datenbank selbst gestört (Down/Netzwerkproblem) oder ist der Connection-Pool durch Last erschöpft, werden Instanzen als &quot;unhealthy&quot; entfernt/neu gestartet. Das behebt die eigentliche Ursache nicht und verschärft Lastspitzen (zusätzliche Reconnects, erhöhte Last auf noch funktionierenden Instanzen).</li><li>Bei LDAP-Störungen ist primär der Login betroffen. Ein Ausfall des Auth-Services aufgrund eines fehlgeschlagenen LDAP-Health-Checks führt jedoch dazu, dass keine Services mehr Berechtigungsinformationen erhalten können – ein systemweiter Ausfall kann die Folge sein.</li></ul><p>Um diese negativen Effekte zu vermeiden, sollen DB- und LDAP-Konnektivität nicht länger den allgemeinen Health-Status bestimmen.</p><p>Sollte die Verbindung zur Datenbank oder LDAP unterbrochen sein, erfolgt automatisch ein Reconnect sobald die Dienste wieder zur Verfügung stehen. Ein Neustart des Services ist dafür nicht notwendig.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><ul><li>In allen Services wird der Datenbank-Health-Check deaktiviert: <code>management.health.db.enabled: false</code>.</li><li>Im Auth-Service wird zusätzlich der LDAP-Health-Check deaktiviert: <code>management.health.ldap.enabled: false</code>.</li></ul><p>Die übrigen Health-/Probe-Indikatoren (z. B. Liveness/Readiness, Info, Prometheus) bleiben unverändert aktiv.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><h3 id="positiv" tabindex="-1">Positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;Positiv&quot;">​</a></h3><ul><li>Verhindert unnötige Restarts bei externen Infrastrukturproblemen (DB/LDAP).</li><li>Erhöht die Stabilität des Gesamtsystems während teilweiser Infrastrukturstörungen.</li></ul><h3 id="negativ" tabindex="-1">Negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;Negativ&quot;">​</a></h3><ul><li>Der Health-Status der Services spiegelt DB-/LDAP-Verfügbarkeit nicht mehr wider. Diese muss über dedizierte Infrastruktur-Monitoring-Lösungen (Datenbank-/LDAP-Monitoring) bzw. anwendungsspezifische Readiness-/Business-Checks beobachtet werden.</li><li>Fehlerbilder durch DB-/LDAP-Ausfälle werden nicht mehr automatisch durch Restart-Strategien auf Service-Ebene adressiert und benötigen operative Gegenmaßnahmen.</li></ul>',13))])}const D=i(o,[["render",u]]);export{p as __pageData,D as default};
